import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Inline CUDA code that fuses the GELU calculation into a single kernel
gelu_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void gelu_kernel(const float* __restrict__ x, float* __restrict__ out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = x[idx];
        float c1 = 0.044715f;
        float c2 = sqrtf(2.0f / 3.14159265358979323846f);
        float inner = val + c1 * val * val * val;
        float out_val = 0.5f * val * (1.0f + tanhf(c2 * inner));
        out[idx] = out_val;
    }
}

torch::Tensor gelu_cuda_forward(torch::Tensor x) {
    auto out = torch::zeros_like(x);
    int size = x.numel();
    const int block_size = 256;
    const int grid_size = (size + block_size - 1) / block_size;
    gelu_kernel<<<grid_size, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), size);
    return out;
}
"""

gelu_cpp_source = r"torch::Tensor gelu_cuda_forward(torch::Tensor x);"

# Build the custom GELU fusion operator
gelu_custom = load_inline(
    name="gelu_custom",
    cpp_sources=gelu_cpp_source,
    cuda_sources=gelu_source,
    functions=["gelu_cuda_forward"],
    verbose=False,
    extra_cflags=[""],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x):
        # Call the custom CUDA kernel for GELU
        return gelu_custom.gelu_cuda_forward(x)

